-- =============================================================================
-- SEED DATA: MODUL 3 - LOGISTIK, INVENTARISASI & WAREHOUSING (NAVALERP)
-- =============================================================================

ON CONFLICT (warehouse_id) DO UPDATE SET warehouse_name = EXCLUDED.warehouse_name, warehouse_code = EXCLUDED.warehouse_code;

ON CONFLICT (location_id) DO NOTHING;

ON CONFLICT (material_id) DO UPDATE SET material_name = EXCLUDED.material_name, unit_price_idr = EXCLUDED.unit_price_idr;

ON CONFLICT (balance_id) DO NOTHING;

ON CONFLICT (instance_id) DO NOTHING;

ON CONFLICT (transfer_id) DO NOTHING;

ON CONFLICT (adjustment_id) DO NOTHING;

ON CONFLICT (transfer_item_id) DO NOTHING;

ON CONFLICT (adj_item_id) DO NOTHING;
